import fs from 'node:fs';
import path from 'node:path';
import {marked} from 'marked';
const X=JSON.parse(fs.readFileSync(process.argv[2],'utf8'));
const historical=p=>/(?:^|\/)(?:old|history|historical|previous-work|archived)(?:\/|$)/i.test(p)||p.includes('preserved-public-snapshots');
const routers=['README.md','architectural-contributions/ecosystem-positioning/README.md','research/ecosystem-awareness/README.md','research/ecosystem-awareness/baseline/README.md','research/ecosystem-awareness/fg-tida/README.md','research/ecosystem-awareness/baseline/fixtures/RS-00E-Q1a/README.md','research/regime-awareness/README.md','standards/minimum-sufficient-control/README.md','submissions/README.md'];
function receiver(source,href){
 let h=href.split('#')[0].split('?')[0];try{h=decodeURIComponent(h);}catch{}
 const same=h.match(/^https?:\/\/(?:github\.com\/dakleyer\/structural-awareness-contributions\/(?:blob|tree)|raw\.githubusercontent\.com\/dakleyer\/structural-awareness-contributions)\/main\/(.*)$/i);
 if(same)return {locality:'same-repository-main',target:same[1]};
 if(/^[a-z][a-z0-9+.-]*:|^\/\//i.test(h))return {locality:'external-or-pinned',target:null};
 return {locality:'relative',target:h?path.posix.normalize(h.startsWith('/')?h.slice(1):path.posix.join(path.posix.dirname(source),h)):source};
}
function assess(bodies,files){
 const occurrences=[],bySource=[],semanticAliases=[],named=[];
 for(const [source,body] of Object.entries(bodies)){
  const start=occurrences.length,tokens=marked.lexer(body,{gfm:true});
  for(const block of tokens)marked.walkTokens([block],t=>{
   if(!['link','image'].includes(t.type)||!/vnext/i.test(t.href))return;
   const raw=t.raw||'',pos=body.indexOf(raw),n=raw?body.split(raw).length-1:0,r=receiver(source,t.href);
   occurrences.push({source,path_subset:historical(source)?'legacy':'working',syntax:/\]\s*\(/.test(raw)?'inline':'reference-style',href:t.href,raw,top_block:block.type,first_literal_line:pos<0?null:body.slice(0,pos).split('\n').length,literal_occurrences:n,position_note:n===1?'Unique literal location':'First literal location only; occurrence ID distinguishes rendered tokens',...r,target_exists:r.target===null?null:files.includes(r.target),source_occurrence_id:occurrences.length-start+1});
  });
  if(start!==occurrences.length)bySource.push({source,path_subset:historical(source)?'legacy':'working',role_status:'unclassified pending logical register; filename is not a role decision',occurrence_count:occurrences.length-start,targets:[...new Set(occurrences.slice(start).map(r=>r.target||r.href))]});
  if(!historical(source)&&/vnext/i.test(path.posix.basename(source)))named.push({path:source,classification:'filename hint only',opening:body.split('\n').slice(0,14).join('\n')});
  if(!historical(source)&&!/vnext/i.test(path.posix.basename(source))&&source.includes('00D_CANONICAL_ARCHITECTURE_BENCHMARK_v0.3'))semanticAliases.push({path:source,classification:'Existing benchmark review alias, retained within its logical source unit; not a newly created VNext',opening:body.split('\n').slice(0,20).join('\n')});
 }
 const inline=occurrences.filter(r=>r.syntax==='inline'),working=inline.filter(r=>r.path_subset==='working');
 return {summary:{markdown:Object.keys(bodies).length,working_markdown:Object.keys(bodies).filter(p=>!historical(p)).length,legacy_markdown:Object.keys(bodies).filter(historical).length,inline_vnext_all:inline.length,inline_vnext_working:working.length,inline_vnext_legacy:inline.length-working.length,reference_style_vnext:occurrences.length-inline.length,working_source_files:new Set(working.map(r=>r.source)).size,working_local_occurrences:working.filter(r=>r.target!==null).length,working_distinct_local_edges:new Set(working.filter(r=>r.target!==null).map(r=>JSON.stringify([r.source,r.target]))).size,working_missing_local_occurrences:working.filter(r=>r.target!==null&&!r.target_exists).length,named_working_vnext_files:named.length,semantic_aliases:semanticAliases.length},source_profiles:bySource,occurrences,named_candidates:named,semanticAliases,controlled_router_edges:occurrences.filter(r=>routers.includes(r.source)),controlled_router_paths:routers};
}

const result=Object.fromEntries(X.heads.map(h=>[h,assess(X.bodies[h],X.trees[h])]));
fs.writeFileSync(process.argv[3],JSON.stringify(result,null,2)+'\n');
